{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Afatinib, the closest analogue sharing the 4-anilinoquinazoline core and crotonamide pharmacophore, is reported to have good oral bioavailability in Phase I clinical studies, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Gefitinib, a 4-anilinoquinazoline EGFR inhibitor, has approximately 60% oral bioavailability in humans, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Erlotinib, another 4-anilinoquinazoline, has absolute oral bioavailability of 76% in cancer patients and 59% in healthy subjects, both well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Simotinib, a close quinazoline analogue, showed good oral bioavailability in advanced NSCLC patients, supporting high oral bioavailability for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Zongertinib, a related quinazoline EGFR inhibitor, was predicted to have 41% human oral bioavailability, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Lapatinib, despite being considered low-bioavailability within this class, still has an estimated oral bioavailability of 30%, above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is dacomitinib, a 4-anilinoquinazoline EGFR inhibitor. The closest analogue afatinib shows good oral bioavailability, and the same chemotype is consistently orally bioavailable in humans (gefitinib ~60%, erlotinib 59-76%, simotinib good, zongertinib predicted 41%). No threshold-relevant evidence supports F < 20%, so the prediction is high.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for dacomitinib is present in the provided evidence.",
    "Afatinib, the closest analogue, is reported as having good oral bioavailability but its absolute bioavailability in humans is not formally known.",
    "Some analogues are described as having 'low' bioavailability in qualitative terms, but numeric estimates remain above the 20% threshold and are less transferable."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

